import {currentOperationsRepository} from '../../backend/operations-admin.mjs';
import {effectiveStore,activeAnnouncement,ukDate,toUKInput,ukInputToISO,safeHref} from '../../operations/model.mjs';
import {renderNewsBody} from '../../operations/news-render.mjs';
export function bootOperationsAdmin({document=globalThis.document,repo=currentOperationsRepository(),confirm=message=>document.defaultView.confirm(message)}={}){
 const d=document,storeForm=d.querySelector('#store-form'),newsForm=d.querySelector('#news-form'),status=d.querySelector('#operations-status');let store=null,posts=[],selected=null,busy=false;
 const field=(form,name)=>form.elements.namedItem(name),say=text=>{status.textContent=text;};
 const node=(tag,text)=>{const n=d.createElement(tag);n.textContent=text;return n;};
 const selection=post=>{selected=post||null;newsForm.reset();for(const name of ['title','slug','excerpt','body','category','publication_at','expires_at','cta_label','cta_url','priority','announcement','dismissible']){const input=field(newsForm,name);if(post){if(input.type==='checkbox')input.checked=post[name];else input.value=name.endsWith('_at')?toUKInput(post[name]):post[name]??'';}}field(newsForm,'slug').readOnly=!!post;d.querySelector('#news-edit-title').textContent=post?'Edit: '+post.title+' · '+post.status:'New draft';d.querySelector('#news-preview').hidden=true;};
 function render(audit){
  const effective=effectiveStore(store),start=store.pause_from?' · Pause starts '+ukDate(store.pause_from):'',end=store.resume_at?' · Reopens '+ukDate(store.resume_at):store.desired_state==='ORDERS_PAUSED'?' · Manual resume':'';
  d.querySelector('#store-current').textContent='Current effective state: '+effective.state+start+end+' (UK time).';
  for(const name of ['customer_title','customer_message','internal_reason'])field(storeForm,name).value=store[name];field(storeForm,'pause_from').value=toUKInput(store.pause_from);field(storeForm,'resume_at').value=toUKInput(store.resume_at);field(storeForm,'mode').value=store.desired_state==='ORDERS_PAUSED'?'edit':'now';field(storeForm,'resume_mode').value=store.resume_at?'scheduled':'manual';updateSchedule();
  const list=d.querySelector('#news-list');list.replaceChildren();if(!posts.length)list.append(node('p','No posts yet.'));for(const p of posts){const button=node('button',p.title+' · '+(p.status==='SCHEDULED'&&Date.parse(p.publication_at)<=Date.now()?'PUBLISHED (effective)':p.status));button.type='button';button.addEventListener('click',()=>selection(p));list.append(button);}
  const active=activeAnnouncement(store,posts.filter(p=>['PUBLISHED','SCHEDULED'].includes(p.status)));d.querySelector('#announcement-current').textContent=active?'Active: '+active.title+(active.dismissible?' · Dismissible':' · Not dismissible'):'No active announcement.';
  const trail=d.querySelector('#operations-audit');trail.replaceChildren();for(const event of audit)trail.append(node('li',ukDate(event.created_at)+' UK · '+event.action+' · '+event.entity_id+' · Admin '+event.actor));if(!audit.length)trail.append(node('li','No operations changes recorded.'));
 }
 const refresh=async()=>{const auditResult=await Promise.all([repo.store(),repo.posts(),repo.audit()]);[store,posts]=auditResult;render(auditResult[2]);};
 async function act(action,message){if(busy)return;busy=true;d.querySelectorAll('button').forEach(b=>b.disabled=true);say('Saving…');try{const result=await action();await refresh();say(message);return result;}catch(error){say(error.message+' Reload current state before retrying if another Admin changed it.');}finally{busy=false;d.querySelectorAll('button').forEach(b=>b.disabled=false);}}
 function updateSchedule(){field(storeForm,'pause_from').disabled=field(storeForm,'mode').value!=='schedule';field(storeForm,'pause_from').required=!field(storeForm,'pause_from').disabled;field(storeForm,'resume_at').disabled=field(storeForm,'resume_mode').value!=='scheduled';field(storeForm,'resume_at').required=!field(storeForm,'resume_at').disabled;}
 storeForm.addEventListener('change',updateSchedule);
 storeForm.addEventListener('submit',event=>{event.preventDefault();if(!store||busy||!storeForm.checkValidity())return;try{const mode=field(storeForm,'mode').value,pause=mode==='schedule'?ukInputToISO(field(storeForm,'pause_from').value):null,resume=field(storeForm,'resume_mode').value==='scheduled'?ukInputToISO(field(storeForm,'resume_at').value):null;
  const start=mode==='schedule'?Date.parse(pause):mode==='edit'?Date.parse(store.pause_from):Date.now();if(mode==='edit'&&store.desired_state!=='ORDERS_PAUSED')throw Error('No existing pause to keep.');if(mode==='schedule'&&start<=Date.now())throw Error('Scheduled pause must be in the future.');if(resume&&Date.parse(resume)<=start)throw Error('Resume must be after the pause starts.');
  if(!confirm('Confirm '+(mode==='schedule'?'scheduled pause at '+ukDate(pause):mode==='edit'?'changes to the existing pause':'pause now')+(resume?' until '+ukDate(resume):' until manual resume')+' (UK time)? New checkout will be blocked; existing orders continue.'))return;
  act(()=>repo.saveStore({desired_state:'ORDERS_PAUSED',mode,pause_from:pause,resume_at:resume,expected_updated_at:store.updated_at,...Object.fromEntries(['customer_title','customer_message','internal_reason'].map(k=>[k,field(storeForm,k).value.trim()]))}),'Store configuration saved.');
 }catch(error){say(error.message);}});
 field(storeForm,'resume').addEventListener('click',()=>{if(store&&!busy&&confirm('Resume new orders now and clear any pause/resume schedule?'))act(()=>repo.saveStore({desired_state:'OPEN',expected_updated_at:store.updated_at}),'Orders are open. Schedule cleared.');});
 field(storeForm,'reload').addEventListener('click',()=>refresh().then(()=>say('Current state reloaded.')).catch(e=>say(e.message)));
 d.querySelector('#new-post').addEventListener('click',()=>selection());
 d.querySelector('#preview-post').addEventListener('click',()=>{const preview=d.querySelector('#news-preview');preview.innerHTML=renderNewsBody(field(newsForm,'body').value);preview.hidden=false;});
 newsForm.addEventListener('submit',async event=>{event.preventDefault();if(busy||!newsForm.checkValidity())return;try{const state=event.submitter?.value||'DRAFT',post=Object.fromEntries(['slug','title','excerpt','body','category','cta_label','cta_url'].map(k=>[k,field(newsForm,k).value.trim()]));if(post.cta_url&&!safeHref(post.cta_url))throw Error('CTA must use a safe /site/path or https:// URL.');if(!!post.cta_url!==!!post.cta_label)throw Error('Provide both CTA label and URL, or leave both blank.');
  post.publication_at=state==='PUBLISHED'?selected?.publication_at||null:ukInputToISO(field(newsForm,'publication_at').value);post.expires_at=ukInputToISO(field(newsForm,'expires_at').value);if(state==='SCHEDULED'&&(!post.publication_at||Date.parse(post.publication_at)<=Date.now()))throw Error('Choose a future UK publication time.');const publication=state==='PUBLISHED'?Math.min(Date.parse(selected?.publication_at)||Date.now(),Date.now()):Date.parse(post.publication_at);if(post.expires_at&&(!Number.isFinite(publication)||Date.parse(post.expires_at)<=publication))throw Error('Expiry must be after publication.');
  Object.assign(post,{status:state,announcement:field(newsForm,'announcement').checked,dismissible:field(newsForm,'dismissible').checked,priority:Number(field(newsForm,'priority').value),...selected?{id:selected.id,expected_updated_at:selected.updated_at}:{}});
  if(!confirm('Confirm '+state.toLowerCase()+' for “'+post.title+'”?'+(['PUBLISHED','SCHEDULED'].includes(state)?' Effective posts are public; Pages refresh may take several minutes.':'')))return;
  const result=await act(()=>repo.savePost(post),'News saved: '+state+'.');if(result)selection(result);
 }catch(error){say(error.message);}});
 selection();const ready=refresh().then(()=>say('Operations ready.')).catch(e=>say(e.message));return {ready,refresh};
}
if(typeof document!=='undefined'&&document.querySelector('#store-form'))bootOperationsAdmin();
